            {
                p_pBackendName = pBackendName is null ? 0 : Marshal.StringToCoTaskMemUTF8(pBackendName);
                fixed (MaBackend* p_pBackend = &pBackend)
                {
                    return GetBackendFromNameNative((byte*)p_pBackendName, (MaBackend*)p_pBackend);
                }
            }
            finally
            {
                if (p_pBackendName != 0)
                    Marshal.FreeCoTaskMem(p_pBackendName);
            }
        }

